            "boolean" => 1,
            "number" => 1,
            "string" => 1,
            "array" => 1,
            "object" => 1,
        );
        %_jm_cst_1 = (
            "null" => 1,
            "bool" => 1,
            "string" => 1,
            "object" => 1,
            "array" => 1,
            "double" => 1,
            "int" => 1,
            "long" => 1,
            "decimal" => 1,
            "binData" => 1,
            "objectId" => 1,
            "date" => 1,
            "regex" => 1,
            "javascript" => 1,
            "timestamp" => 1,
            "minKey" => 1,
            "maxKey" => 1,
        );
        %check_model_map = (
            "" => \&json_model_3,
            "schema" => \&json_model_3,
        );
    }
}

sub check_model_free()
{
    if ($initialized)
    {
        $initialized = 0;
        %json_model_3_map = ();
        %_jm_cst_0 = ();
        %_jm_cst_1 = ();
        %check_model_map = ();
    }
}

sub check_model_mapper($)
{
    my ($name) = @_;
    die "unexpected model name \"$name\"" unless exists $check_model_map{$name};
    return $check_model_map{$name};
}

sub check_model($$$)
{
    my ($json, $name, $rep) = @_;
    die "unexpected model name \"$name\"" unless exists $check_model_map{$name};
    my $path = defined $rep ? [] : undef;
    return $check_model_map{$name}($json, $path, $rep);
}

#
# SCRIPT EXECUTION
#
check_model_init();
jm_main(\&check_model, \%check_model_map, JMC_VERSION);
check_model_free();
